fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr.len() > 0, for length == 1, it's trivially sorted.
    // We check adjacent pairs for nondecreasing order.
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}